// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= type(uint256).max);
        // Expect the event BetLimitChanged to be emitted
        vm.expectEmit(true, true, true, true);
        emit BetLimitChanged(amount);
        c.AdjustBetAmounts(amount);
        // After the call, the betLimit state variable should equal the passed amount
        assertTrue(c.currentBetLimit() == amount);
    }
    event BetLimitChanged(uint256 currentBetLimit);
}

